
// AIDNode public site. Standalone asset bundle; no external requests, cookies, trackers or user state.
const AIDNODE_ASSETS = {
  '/assets/aidnode-emblem.webp': {type:'image/webp',data:''},
  '/assets/aidnode-logo.webp': {type:'image/webp',data:''},
  '/assets/aidnode-white.webp': {type:'image/webp',data:''},
  '/assets/favicon.png': {type:'image/png',data:''},
  '/favicon.ico': {type:'image/x-icon',data:''},
};
function aidnodeAsset(path){
  const a=AIDNODE_ASSETS[path];
  if(!a)return null;
  const decoded=Uint8Array.from(atob(a.data),c=>c.charCodeAt(0));
  return new Response(decoded,{status:200,headers:{'content-type':a.type,'cache-control':'public,max-age=604800,immutable','x-content-type-options':'nosniff'}});
}
