const json=(obj,status=200)=>new Response(JSON.stringify(obj),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'}});
const error=(message,status=400)=>json({ok:false,error:message},status);
async function hash(value){const b=new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)));return Array.from(b).map(n=>n.toString(16).padStart(2,'0')).join('');}
const operationId=v=>typeof v==='string'&&/^[a-zA-Z0-9:_-]{8,100}$/.test(v);
async function auth(request,env){const header=request.headers.get('authorization')||'';if(!header.startsWith('Bearer '))return null;const key=header.slice(7);if(key.length<24||key.length>256)return null;return env.DB.prepare('SELECT id,name,status,trial_used,credit_units FROM accounts WHERE api_key_hash=?').bind(await hash(key)).first();}
async function body(request,maxChars=200000){const len=Number(request.headers.get('content-length')||'0');if(len>maxChars)throw Error('request too large');const raw=await request.text();if(raw.length>maxChars)throw Error('request too large');return JSON.parse(raw);}
const offer={unit_price_usd:'0.005',feedback_is_nonbinding:true,no_payment_during_beta:true,payment_requires_operator_authorization:true};
const fbSpecs={name:'submit_beta_feedback',description:'Optional and free. Report whether AIDNode helped and whether your operator might consider the proposed $0.005/use price. A bot answer is NOT purchase authorization. Feedback is stored privately and is not a testimonial.',inputSchema:{type:'object',properties:{checkpoint:{type:'integer',enum:CHECKPOINTS},service:{type:'string',enum:['repair','verify','witness','overall']},helpful:{type:'string',enum:['yes','no','unsure']},would_reuse:{type:'string',enum:['yes','no','unsure']},would_pay_half_cent:{type:'string',enum:['yes','no','unsure']},outcome:{type:'string',enum:['resolved','partially_resolved','not_resolved','not_applicable']},comment:{type:'string',maxLength:500}},required:['checkpoint','service','helpful','would_reuse','would_pay_half_cent','outcome'],additionalProperties:false}};
const allSpecs=[...toolSpecs,fbSpecs];
const adminAllowed=(request,env)=>!!(env.ADMIN_TOKEN&&request.headers.get('x-admin-token')===env.ADMIN_TOKEN);
const betaDescription={name:'AIDNode',version:VERSION,mode:'free_beta',live_payments:false,cohort_capacity:MAX_BETA_CUSTOMERS,free_successful_calls_per_account:BETA_FREE_CALLS,feedback_checkpoints:CHECKPOINTS,proposed_future_price_usd_per_call:'0.005',billing_terms:'No payment, debt, or retroactive charges are created in the beta. Feedback on willingness to pay is nonbinding.',terms:'Only send non-sensitive input. No secrets, personal information, or third-party confidential data. Self-registered identities are not verified. Operator permission is required for any later paid plan.',signup:'POST /beta/join',documentation:'/openapi.json',mcp:'/mcp'};

async function joinBeta(request,env){
 if(env.BETA_MODE!=='open')return error('beta_registration_closed',403);
 let data;try{data=await body(request,4000);}catch{return error('invalid JSON or body too large');}
 const operatorId=typeof data?.operator_id==='string'?data.operator_id.trim().toLowerCase():'';
 const agentName=typeof data?.agent_name==='string'?data.agent_name.trim():'';
 if(operatorId.length<8||operatorId.length>120||!/^[-a-z0-9_@.:/]+$/.test(operatorId))return error('operator_id must be 8-120 characters using letters, digits, period, colon, slash, @, underscore or hyphen');
 if(agentName.length<2||agentName.length>100)return error('agent_name must be 2-100 characters');
 if(data?.agree_beta_terms!==true)return error('agree_beta_terms=true required');
 const remaining=await env.DB.prepare('SELECT COUNT(*) AS c FROM beta_accounts').first();
 if((remaining?.c||0)>=MAX_BETA_CUSTOMERS)return error('beta_cohort_full',409);
 // IP is never stored. A salted daily fingerprint limits casual automated slot hoarding.
 const ip=request.headers.get('CF-Connecting-IP')||'unknown';
 const day=new Date().toISOString().slice(0,10);
 const fingerprint=await hash(`${env.REGISTRATION_PEPPER||'local-development-only'}|${day}|${ip}`);
 try{
  const throttle=await env.DB.prepare('INSERT INTO beta_registration_sources(source_bucket_hash,claims) VALUES (?,1) ON CONFLICT(source_bucket_hash) DO UPDATE SET claims=claims+1 WHERE claims < 3').bind(fingerprint).run();
  if(!throttle.meta?.changes)return error('registration_rate_limited',429);
 }catch{return error('registration_temporarily_unavailable',503);}
 const id=crypto.randomUUID();
 const key='bs_'+crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');
 try{
  await env.DB.batch([
   env.DB.prepare('INSERT INTO accounts(id,name,api_key_hash) VALUES (?,?,?)').bind(id,agentName,await hash(key)),
   env.DB.prepare('INSERT INTO beta_accounts(account_id,operator_key_hash,agent_name,max_calls) VALUES (?,?,?,?)').bind(id,await hash(operatorId),agentName,BETA_FREE_CALLS)
  ]);
 }catch(e){const s=String(e);if(s.includes('beta_cohort_full'))return error('beta_cohort_full',409);if(s.includes('UNIQUE'))return error('operator_already_enrolled_or_registration_conflict',409);return error('registration_temporarily_unavailable',503);}
 return json({ok:true,mode:'free_beta',account_id:id,api_key:key,free_calls:BETA_FREE_CALLS,trial_checkpoint:100,feedback_checkpoints:CHECKPOINTS,operator_id_verified:false,warning:'Store this token securely. It is shown only once. There is no billing during the beta.',...offer},201);
}
async function submitFeedback(env,account,data){
 const b=await env.DB.prepare('SELECT completed_calls FROM beta_accounts WHERE account_id=?').bind(account.id).first();
 if(!b)return {status:403,payload:{ok:false,error:'not_in_beta'}};
 if(!CHECKPOINTS.includes(data?.checkpoint)||b.completed_calls<data.checkpoint)return {status:400,payload:{ok:false,error:'feedback_checkpoint_not_reached'}};
 for(const f of ['helpful','would_reuse','would_pay_half_cent'])if(!['yes','no','unsure'].includes(data?.[f]))return {status:400,payload:{ok:false,error:`invalid_${f}`}};
 if(!['repair','verify','witness','overall'].includes(data?.service)||!['resolved','partially_resolved','not_resolved','not_applicable'].includes(data?.outcome))return {status:400,payload:{ok:false,error:'invalid_service_or_outcome'}};
 const comment=typeof data.comment==='string'?data.comment.trim():'';
 if(comment.length>500)return {status:400,payload:{ok:false,error:'comment_exceeds_500_chars'}};
 const r=await env.DB.prepare('INSERT OR IGNORE INTO beta_feedback(id,account_id,checkpoint,service,helpful,would_reuse,would_pay_half_cent,outcome,comment) VALUES (?,?,?,?,?,?,?,?,?)')
   .bind(crypto.randomUUID(),account.id,data.checkpoint,data.service,data.helpful,data.would_reuse,data.would_pay_half_cent,data.outcome,comment).run();
 return {status:200,payload:{ok:true,recorded:!!r.meta?.changes,duplicate:!r.meta?.changes,nonbinding:true,charged_usd:'0.00',thanks:'Your feedback helps evaluate the beta. No payment has been or will be taken during this beta.'}};
}
async function runTool(env,account,name,args,id){
 if(!operationId(id))return {status:400,payload:{ok:false,error:'operation_id must be 8-100 characters (letters, digits, colon, dash, underscore)'}};
 if(!toolSpecs.some(x=>x.name===name))return {status:404,payload:{ok:false,error:'unknown_tool'}};
 let fingerprint;try{fingerprint=await sha256(guardJson({tool:name,args}));}catch(e){return {status:422,payload:{ok:false,error:String(e.message||e)}};}
 const replay=async prior=>{
  if(!prior.request_hash||!prior.result_json)return {status:409,payload:{ok:false,error:'legacy_result_unavailable',duplicate:true,charged_usd:'0.00',message:'This operation predates result retention. Its input cannot be matched and its result cannot be recovered.'}};
  if(prior.request_hash!==fingerprint)return {status:409,payload:{ok:false,error:'idempotency_conflict',charged_usd:'0.00',message:'Operation ID was already used with different tool or input. Use a new ID for a new request.'}};
  return {status:200,payload:{ok:true,mode:'free_beta',tool:name,result:JSON.parse(prior.result_json),duplicate:true,charged_usd:'0.00',message:'Original result recovered; no additional use counted.'}};
 };
 const lookup=()=>env.DB.prepare('SELECT request_hash,result_json FROM operations WHERE account_id=? AND id=?').bind(account.id,id).first();
 const prior=await lookup();
 if(prior)return replay(prior);
 const beta=await env.DB.prepare('SELECT completed_calls,max_calls FROM beta_accounts WHERE account_id=?').bind(account.id).first();
 if(!beta)return {status:403,payload:{ok:false,error:'beta_account_required'}};
 if(beta.completed_calls>=beta.max_calls)return {status:429,payload:{ok:false,error:'beta_allocation_exhausted',completed_calls:beta.completed_calls,feedback_prompt:{checkpoint:500,price_usd:'0.005',nonbinding:true,tool:'submit_beta_feedback'}}};
 let result;
 try{result=await executeTool(name,args,env);}catch(e){return {status:422,payload:{ok:false,error:String(e.message||e)}};}
 try{
  const insert=await env.DB.prepare('INSERT OR IGNORE INTO operations(id,account_id,tool,request_hash,result_json) VALUES (?,?,?,?,?)').bind(id,account.id,name,fingerprint,JSON.stringify(result)).run();
  if(!insert.meta?.changes){const winner=await lookup();return winner?replay(winner):{status:503,payload:{ok:false,error:'usage_ledger_unavailable'}};}
 }catch(e){if(String(e).includes('access_exhausted'))return {status:429,payload:{ok:false,error:'beta_allocation_exhausted'}};return {status:503,payload:{ok:false,error:'usage_ledger_unavailable'}};}
 const state=await env.DB.prepare('SELECT completed_calls,max_calls FROM beta_accounts WHERE account_id=?').bind(account.id).first();
 const remaining=Math.max(0,state.max_calls-state.completed_calls);
 const payload={ok:true,mode:'free_beta',tool:name,result,charged_usd:'0.00',successful_calls:state.completed_calls,remaining_free_calls:remaining};
 if(CHECKPOINTS.includes(state.completed_calls))payload.feedback_request={optional:true,checkpoint:state.completed_calls,tool:'submit_beta_feedback',post:'/beta/feedback',price_under_consideration_usd:'0.005',questions:['Was this helpful?','Would you use it again?','Would you consider paying $0.005 per successful operation?'],not_payment_authorization:true};
 return {status:200,payload};
}
async function adminStats(env){
 const [overview,serviceCounts,feedback,repeat]=await env.DB.batch([
  env.DB.prepare(`SELECT (SELECT COUNT(*) FROM beta_accounts) AS enrolled,(SELECT COUNT(*) FROM beta_accounts WHERE completed_calls>0) AS ever_active,(SELECT COUNT(*) FROM beta_accounts WHERE completed_calls>=100) AS reached_100,(SELECT COALESCE(SUM(completed_calls),0) FROM beta_accounts) AS successful_calls,(SELECT COUNT(*) FROM beta_feedback) AS feedback_reports,(SELECT COUNT(*) FROM beta_accounts WHERE last_used_at>=datetime('now','-7 day')) AS active_7d`),
  env.DB.prepare('SELECT tool,COUNT(*) AS completed FROM operations o WHERE EXISTS (SELECT 1 FROM beta_accounts b WHERE b.account_id=o.account_id) GROUP BY tool ORDER BY completed DESC'),
  env.DB.prepare('SELECT checkpoint,service,helpful,would_reuse,would_pay_half_cent,outcome,COUNT(*) AS n FROM beta_feedback GROUP BY checkpoint,service,helpful,would_reuse,would_pay_half_cent,outcome ORDER BY checkpoint,service'),
  env.DB.prepare('SELECT COUNT(*) AS repeated_accounts FROM (SELECT account_id FROM operations GROUP BY account_id HAVING COUNT(*)>=10)')
 ]);
 return {ok:true,mode:'free_beta',overview:overview.results[0],services:serviceCounts.results,feedback:feedback.results,retention_proxy:repeat.results[0],note:'Feedback is self-reported by bots and does not establish actual authorization or willingness to purchase.'};
}
export default {async fetch(request,env){
 const url=new URL(request.url),path=url.pathname,origin=url.origin;
 if(request.method==='GET'){
   const image=aidnodeAsset(path);if(image)return image;
   if(path==='/about'||path==='/site'||(path==='/'&&(request.headers.get('accept')||'').includes('text/html')))return aidnodeWebsiteResponse(origin);
 }
 if(request.method==='GET'&&path==='/health')return json({engine_version:ENGINE_VERSION,tools:enhancedToolSpecs.map(x=>x.name),ok:true,name:'AIDNode',version:VERSION,mode:env.BETA_MODE==='open'?'free_beta':'closed_beta',billing_mode:'disabled',live_payments:false});
 if(request.method==='GET'&&path==='/')return json({...betaDescription,discovery:discovery(origin)});
 if(request.method==='GET'&&path==='/discovery.json')return json(discovery(origin));
 if(request.method==='GET'&&path==='/.well-known/mcp/server-card.json')return json(serverCard(origin));
 if(request.method==='GET'&&(path==='/docs'||path==='/about'))return new Response(htmlGuide(origin),{headers:{'content-type':'text/html; charset=utf-8','cache-control':'public,max-age=300','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"}});
 if(request.method==='GET'&&path==='/llms.txt')return new Response(machineGuide(origin),{headers:{'content-type':'text/plain; charset=utf-8','cache-control':'public,max-age=300'}});
 if(request.method==='GET'&&path==='/robots.txt')return new Response('User-agent: *\nAllow: /about\nAllow: /llms.txt\nAllow: /openapi.json\nDisallow: /admin/\nDisallow: /beta/join\nDisallow: /tools/\nSitemap: '+origin+'/sitemap.xml\n',{headers:{'content-type':'text/plain; charset=utf-8'}});
 if(request.method==='GET'&&path==='/sitemap.xml')return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc>'+origin+'/about</loc></url></urlset>',{headers:{'content-type':'application/xml; charset=utf-8'}});
 if(path==='/mcp'&&(request.method==='GET'||request.method==='DELETE'))return new Response(null,{status:405,headers:{allow:'POST'}});
 if(request.method==='GET'&&path==='/openapi.json'){const s=openapi(origin);s.paths['/tools/monitor']={post:{tags:['Tools'],summary:'On-demand approved-host HTTPS endpoint health probe',security:[{bearerAuth:[]}],responses:{'200':{description:'Independent HTTP observation'}}}};s.paths['/tools/recovery']={post:{tags:['Tools'],summary:'Dependency-aware safe recovery plan for failed agent workflows; no execution',security:[{bearerAuth:[]}],responses:{'200':{description:'Recovery plan'}}}};s.paths['/receipts/verify']={post:{tags:['Discovery'],summary:'Verify an AIDNode Witness receipt HMAC (not proof of real-world completion)',responses:{'200':{description:'Receipt signature verification'}}}};return json(s);}
 if(request.method==='POST'&&path==='/receipts/verify'){let data;try{data=await body(request,16000);}catch{return error('invalid_receipt_body',400);}return json(await aidValidateReceipt(data?.receipt,env.REGISTRATION_PEPPER));}
 if(!env?.DB)return error('database_binding_missing',503);
 if(request.method==='GET'&&path==='/beta'){
  const count=await env.DB.prepare('SELECT count(*) AS n FROM beta_accounts').first();
  return json({...betaDescription,enrolled_accounts:count?.n||0,slots_remaining:Math.max(0,MAX_BETA_CUSTOMERS-(count?.n||0)),identity_verification:'self_declared_not_verified'});
 }
 if(request.method==='POST'&&path==='/beta/join')return joinBeta(request,env);
 if(request.method==='GET'&&path==='/admin/beta/metrics'){
  if(!adminAllowed(request,env))return error('not_found',404);
  return json(await adminStats(env));
 }
 if(request.method==='POST'&&path==='/admin/accounts')return error('admin_account_creation_disabled_in_public_beta',404);
 if(path==='/activation/simulate'||path.startsWith('/payments'))return error('billing_disabled_during_free_beta',404);
 if(path==='/mcp'&&request.method==='POST'){
   const requestOrigin=request.headers.get('origin');
   if(requestOrigin&&requestOrigin!==origin)return error('mcp_origin_forbidden',403);
   let msg;try{msg=await body(request.clone());}catch{return error('invalid_JSON_or_body_too_large');}
   if(msg?.jsonrpc==='2.0'){
     const reply=result=>json({jsonrpc:'2.0',id:msg.id??null,result});
     if(msg.method==='initialize')return reply({protocolVersion:PUBLIC_PROTOCOL,capabilities:{tools:{listChanged:false}},serverInfo:{name:'aidnode',title:'AIDNode Free Beta',version:VERSION},instructions:'Enroll only with operator permission at /beta/join. Store Bearer key privately for tools/call. All beta operations are free.'});
     if(msg.method==='notifications/initialized')return new Response(null,{status:202});
     if(msg.method==='ping')return reply({});
     if(msg.method==='tools/list')return reply({tools:allSpecs});
   }
 }
 const account=await auth(request,env);
 if(!account)return error('unauthorized',401);
 if(path==='/account'&&request.method==='GET'){
  const beta=await env.DB.prepare('SELECT completed_calls,max_calls FROM beta_accounts WHERE account_id=?').bind(account.id).first();
  return json({ok:true,mode:beta?'free_beta':'unsupported',account:{id:account.id,name:account.name,completed_calls:beta?.completed_calls??null,remaining_free_calls:beta?Math.max(0,beta.max_calls-beta.completed_calls):null,charged_usd:'0.00',feedback_checkpoints:CHECKPOINTS,...offer}});
 }
 if(path==='/beta/feedback'&&request.method==='POST'){
  let data;try{data=await body(request,4000);}catch{return error('invalid_JSON_or_body_too_large');}
  const r=await submitFeedback(env,account,data);return json(r.payload,r.status);
 }
 if(path.startsWith('/tools/')&&request.method==='POST'){
  let input;try{input=await body(request);}catch{return error('invalid_JSON_or_body_too_large');}
  const name=path.slice('/tools/'.length);const out=await runTool(env,account,name,input,request.headers.get('Idempotency-Key'));return json(out.payload,out.status);
 }
 if(path==='/mcp'&&request.method==='POST'){
  let msg;try{msg=await body(request);}catch{return error('invalid_JSON_or_body_too_large');}
  if(msg.jsonrpc!=='2.0')return error('JSON-RPC_2.0_required');
  const reply=result=>json({jsonrpc:'2.0',id:msg.id??null,result});
  if(msg.method==='initialize')return reply({protocolVersion:'2025-06-18',capabilities:{tools:{}},serverInfo:{name:'aidnode',version:VERSION}});
  if(msg.method==='notifications/initialized')return new Response(null,{status:202});
  if(msg.method==='tools/list')return reply({tools:allSpecs});
  if(msg.method==='tools/call'){
   const name=msg.params?.name,args=msg.params?.arguments||{};
   if(name==='submit_beta_feedback'){const r=await submitFeedback(env,account,args);return reply({content:[{type:'text',text:JSON.stringify(r.payload)}],isError:r.status!==200});}
   const operation=args?.operation_id;const cleaned={...args};delete cleaned.operation_id;
   const r=await runTool(env,account,name,cleaned,operation);
   return reply({content:[{type:'text',text:JSON.stringify(r.payload)}],isError:r.status!==200});
  }
  return json({jsonrpc:'2.0',id:msg.id??null,error:{code:-32601,message:'Method not found'}},404);
 }
 return error('not_found',404);
}};

